def main():
    rows = []
    for role in sorted(TECHNICAL):
        technical_pool = TECHNICAL[role]
        for difficulty, wanted in COMPOSITION.items():
            behavioural = pick(BEHAVIOURAL, wanted)
            technical = pick(technical_pool, wanted)
            # A mixed interview is what a student actually sits: a couple of
            # questions about them, then the ones about the work.
            mixed = behavioural[:2] + technical[:3]

            for session_type, questions in (
                ("behavioural", behavioural),
                ("technical", technical),
                ("mixed", mixed),
            ):
                rows.append((role, session_type, difficulty, questions))

    print("-- Generated by supabase/seed/interview_bank.py. Do not edit by hand.")
    print("--")
    print("-- interview_question_bank is a cache: the first student to ask for a")
    print("-- (role, type, difficulty) pays one of three daily AI actions, and")
    print("-- everybody after them gets it free. It has been empty since it was")
    print("-- created in 0008, so every student has been paying for questions the")
    print("-- last one already generated.")
    print("--")
    print("-- Seeding it makes interview practice cost nothing from today. The")
    print("-- questions are hand-written so they are reviewable in git, do not")
    print("-- drift when a model changes, and can be specific to the market these")
    print("-- students are actually interviewing in.")
    print()
    print(f"-- {len(rows)} sets: 10 roles x 3 session types x 3 difficulties.")
    print()

    print("insert into public.interview_question_bank")
    print("  (role_slug, session_type, difficulty, questions)")
    print("values")
    values = []
    for role, session_type, difficulty, questions in rows:
        values.append(
            f"  ({sql_string(role)}, {sql_string(session_type)}::interview_type, "
            f"{sql_string(difficulty)}::difficulty_level, {json_literal(questions)}::jsonb)"
        )
    print(",\n".join(values))
    print("on conflict (role_slug, session_type, difficulty) do update")
    print("  set questions = excluded.questions;")
    print()

    # ---------------------------------------------------------------- companies
    print("-- ------------------------------------------------------ company packs")
    print("--")
    print("-- What a student actually wants the night before: not 'behavioural,")
    print("-- medium' but 'I have an interview at bKash on Thursday'. Public")
    print("-- reference data like career_paths, readable by any signed-in student.")
    print("""
create table if not exists public.company_interview_packs (
  slug       text primary key,
  name       text not null,
  about      text not null,
  questions  jsonb not null,
  created_at timestamptz not null default now()
);

alter table public.company_interview_packs enable row level security;
alter table public.company_interview_packs force row level security;

drop policy if exists company_interview_packs_read on public.company_interview_packs;
create policy company_interview_packs_read on public.company_interview_packs
  for select to authenticated using (true);

comment on table public.company_interview_packs is
  'Employers Bangladeshi students actually apply to, and what each is known '
  'to ask. Reference data, seeded, not user-generated.';
""")
    print("insert into public.company_interview_packs (slug, name, about, questions)")
    print("values")
    company_values = []
    for slug, name, about, questions in COMPANIES:
        payload = [{"question": q, "category": "company"} for q in questions]
        company_values.append(
            f"  ({sql_string(slug)}, {sql_string(name)}, {sql_string(about)}, "
            f"{json_literal(payload)}::jsonb)"
        )
    print(",\n".join(company_values))
    print("on conflict (slug) do update set")
    print("  name = excluded.name, about = excluded.about,")
    print("  questions = excluded.questions;")
    print()

    print("""-- ------------------------------------------------------------------- checked
do $$
declare
  v_sets int;
  v_thin int;
begin
  select count(*) into v_sets from public.interview_question_bank;
  if v_sets < 90 then
    raise exception 'expected 90 seeded sets, found %', v_sets;
  end if;

  -- The endpoint slices to the requested count, which defaults to five. A set
  -- with fewer would silently hand a student a shorter interview.
  select count(*) into v_thin from public.interview_question_bank
   where jsonb_array_length(questions) < 5;
  if v_thin > 0 then
    raise exception '% seeded sets have fewer than five questions', v_thin;
  end if;

  if (select count(*) from public.company_interview_packs) < 6 then
    raise exception 'the company packs did not seed';
  end if;
end $$;""")


if __name__ == "__main__":
    main()
